$("login").onsubmit=async e=>{e.preventDefault();cred=$("cred").value;const b=e.submitter;if(b)b.disabled=true;const ok=await carregar();if(b)b.disabled=false;if(ok){$("cred").value="";entrou()}else cred=""};
$("setup").onsubmit=async e=>{e.preventDefault();const a=$("new1").value,b=$("new2").value;$("err2").textContent="";if(a.length<16){$("err2").textContent="Use pelo menos 16 caracteres.";return}if(a!==b){$("err2").textContent="As duas credenciais não são iguais.";return}
  const r=await fetch("/api/painel",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({criar:a})});if(!r.ok){$("err2").textContent=await r.text();return}
  cred=a;$("new1").value=$("new2").value="";if(await carregar())entrou();else{$("setup").classList.add("hidden");$("login").classList.remove("hidden")}};
