function demoData(sp){let s=sp==="teste"?11:7;const R=()=>{s=(s*16807)%2147483647;return s/2147483647};const ri=(a,b)=>a+Math.floor(R()*(b-a+1));const f=sp==="teste"?.06:1;
  const ideos=["Comunista","Anarquista","Extrema esquerda","Socialista democrático","Social-democrata","Esquerda progressista","Ecologista","Esquerda conservadora","Nacional-desenvolvimentista","Centrista","Social-liberal","Democracia cristã","Liberal progressista","Liberal clássico","Libertário","Anarcocapitalista","Liberal-conservador","Conservador","Direita nacional-conservadora","Extrema direita","Fascista"];
  const w=[1,0,2,6,14,7,3,6,4,9,5,4,3,6,3,1,6,9,8,2,0].map(x=>Math.round(x*f));const N=w.reduce((a,b)=>a+b,0);const porIdeologia=Object.fromEntries(ideos.map((n,i)=>[n,w[i]]));
  const eixos={},medias={},medianas={};for(const k of "EACNDS"){eixos[k]={};for(let v=-100;v<=100;v+=20)eixos[k][v]=Math.max(0,Math.round(N*Math.exp(-((v-(k==="D"?-60:k==="S"?10:0))**2)/3000)/5+ri(-1,2)*f));medias[k]=k==="D"?-61:k==="S"?12:ri(-12,12);medianas[k]=medias[k]+ri(-5,5)}
  const bussola={};for(let i=0;i<N;i++){const e=Math.round((ri(-90,80))/20)*20,a=Math.round((ri(-70,80))/20)*20;bussola[e+","+a]=(bussola[e+","+a]||0)+1}
  const perguntas=Object.keys(CANON).map(id=>{const n=Math.round((id[0]==="P"?ri(2,12):ri(20,Math.max(21,N)))*f)+1;const x=ri(0,3),a=ri(0,n/3|0),b=ri(0,n/4|0),c=ri(0,n/5|0),d=ri(0,n/4|0);return {id,a,b,c,d,e:Math.max(0,n-x-a-b-c-d),x,apresentada:n,abertas:ri(0,n/3|0)}});
  const qualidade={};for(const k of "EACNDS"){qualidade[k]={n:62,alfa:[.81,.72,.84,.63,.77,.58]["EACNDS".indexOf(k)],itens:Object.keys(CANON).filter(id=>id[0]===k).map(id=>({id,r:Math.round((R()*.7-.05)*100)/100}))}}
  const porDia={};for(let i=0;i<14;i++){const d=new Date(Date.now()-3*3600e3-i*864e5).toISOString().slice(0,10);porDia[d]=sp==="teste"?(i<2?ri(1,3):0):(i>11?0:ri(2,14))}
  return {total:N,hoje:porDia[new Date(Date.now()-3*3600e3).toISOString().slice(0,10)],porModo:{essencial:Math.round(N*.35),padrao:Math.round(N*.45),aprofundado:N-Math.round(N*.35)-Math.round(N*.45)},porDia,porIdeologia,tempo:{"<5":4,"5-10":21,"10-15":34,"15-20":22,"20-30":10,"30+":3},
    idade:{"18-24":31,"25-34":28,"35-44":12,"45-59":8,"60+":3,"Não informou":12},uf:{SP:48,RJ:11,MG:9,PR:5,RS:4,BA:3,"Não informou":14},comDemografia:80,
    cruzamento:{"18-24":{"Social-democrata":6,"Conservador":5,"Centrista":"<5"},"25-34":{"Social-democrata":5,"Conservador":"<5","Centrista":5},"35-44":null},
    eixos,medias,medianas,bussola,extremos:{com:{media:18,forte:1,n:22},anq:{media:9,forte:0,n:30},fas:{media:6,forte:1,n:N},anc:{media:14,forte:1,n:19}},perguntas,
    confianca:{alta:61,media:24,baixa:9},desempates:3,inconsistenciaMedia:.4,espectro:{"Esquerda":14,"Centro-esquerda":19,"Centro":21,"Centro-direita":17,"Direita":12,"Não me identifico com nenhum":5,"Não informou":6},
    espectroEconomia:{"Esquerda":-52,"Centro-esquerda":-24,"Centro":-3,"Centro-direita":21,"Direita":46},autoid:{"Social-democrata":{"Social-democrata":9,"Socialista democrático":"<5"},"Conservador":{"Conservador":7,"Direita nacional-conservadora":5}},
    autoN:71,autoAcerto:39,funil:{inicios:Math.round(N*1.3),saidas:{"1-10":9,"11-20":7,"21-30":5,"31-40":6},conclusoes:N,conclusoesComInicio:Math.round(N*.9)},legado:sp==="real"?19:0,qualidade,pesos:null,minPesos:100,geradoEm:new Date().toISOString()}}
